"""Гл. 9 — пакет G (G0 Агнис/мать, G1 крупные, G2 мелкие, D дефицифровка). Неидемпотентен."""
import sys, pathlib
P = pathlib.Path("03-manuscript/arc-02/ch-09.md")
t = P.read_text(encoding="utf-8")
n = 0
def R(old, new):
    global t, n
    c = t.count(old)
    if c != 1:
        print("FAIL count=%d: %r" % (c, old[:90])); sys.exit(1)
    t = t.replace(old, new); n += 1

